-- 0001: the flat sales spreadsheet, loaded as it arrived.
--
-- Stockroom's first customer (a wholesale distributor) kept a year of sales
-- (1 Dec 2025 to 27 Nov 2026) in one spreadsheet: one row per order line,
-- with the customer's name, email and city and the product's name, category
-- and price typed again on every row. This table is that spreadsheet, kept
-- in its own `staging` schema so it is never mistaken for the real design.
-- Migrations 0002 onward normalize it into 1NF, 2NF and 3NF tables.
--
-- It is deliberately left as messy as the original:
--   - 7 rows squeeze two products into one cell ("Rolled Oats 1kg, Kettle
--     Chips 150g"), with their categories, prices and quantities likewise
--     comma-separated. That's why unit_price and quantity are text here: a
--     cell can hold more than one number. (This breaks first normal form.)
--   - Corner Market moved from Austin to Round Rock in June 2026. Most later
--     rows say Round Rock, but a few were copied from old rows and still say
--     Austin, so the sheet can't tell you where the customer is.
--   - Bluebonnet Grocers' email is typed two ways.
--   - Trail Mix is filed under Snacks on most rows and Pantry on some.
--   - Olive Oil 1L went from 11.99 to 12.99 on 1 June 2026. Earlier rows keep
--     the old price, which is correct: it's what the customer paid.
--   - Old Town Grocer placed one order, the only sale of the bulk olive oil.
--
-- row_number is the spreadsheet's row number, the only thing that identifies
-- a row here: the order number repeats once per line, and nothing else is unique.

CREATE SCHEMA staging;

CREATE TABLE staging.flat_sales (
  row_number     integer PRIMARY KEY,
  order_number   text    NOT NULL,
  order_date     date    NOT NULL,
  customer_name  text    NOT NULL,
  customer_email text    NOT NULL,
  customer_city  text    NOT NULL,
  product_name   text    NOT NULL,
  category       text    NOT NULL,
  unit_price     text    NOT NULL,
  quantity       text    NOT NULL
);

COMMENT ON TABLE staging.flat_sales IS 'The raw sales spreadsheet (one row per order line, facts repeated). Source for the normalized tables; never queried by tools except compare_designs.';

